// Generated by Suite Builder from a crawl of the site. The plain-English steps of the running test.
// EDIT RULES: edit only inside YOURS blocks; regenerating keeps them and rewrites the rest of this file.
/**
 * The running test's steps in plain English: "Open the home page (/)", "Click "Services" in the
 * header", "Check that the submit button is shown". Every action and check in the suite adds its step
 * here, in Cypress's command log and in the terminal, so a run's output reads like the story it tests.
 * When a test fails, the support file prints the step it failed at, and why.
 */
import { shared } from './Shared';

/** One log per test window, whichever bundle writes to it (Shared.ts). */
const steps = shared<string[]>('steps', () => []);

export const StepLog = {
  /** Starts a new test's log. The support file calls this before every test. */
  start(): void {
    steps.length = 0;
  },

  /** A step the test takes, as a visitor would say it: step('Type the email address'). */
  step(sentence: string): void {
    cy.then(() => {
      steps.push(sentence);
      Cypress.log({ name: 'step', displayName: `${steps.length}.`, message: sentence });
      return cy.task('suiteLog', `   ${steps.length}. ${sentence}`, { log: false });
    });
  },

  /** A remark that is not a step of its own, e.g. "now on the services page". */
  note(remark: string): void {
    cy.then(() => cy.task('suiteLog', `      ${remark}`, { log: false }));
  },

  /** The steps so far, in order. */
  steps(): string[] {
    return [...steps];
  },

  /**
   * Why something failed, in one line: the first line of the message, without Cypress's "Timed out
   * retrying" prefix. A page or address that did not answer says which, and the network's own error:
   * "`cy.visit()` could not load https://x.test/contact/: connect ETIMEDOUT 192.0.2.1:443", where Cypress's
   * first line ends at "failed trying to load:" (Site G's run). An address that took no connection is
   * named, with how to see the others: Cypress tries one address, where a browser tries the next.
   */
  reason(error: Error): string {
    const lines = (error.message || error.name).split('\n').map((l) => l.trim());
    const first = lines[0];
    if (first.endsWith('failed trying to load:')) {
      const url = lines.slice(1).find((l) => /^https?:\/\//.test(l));
      const network = lines.find((l) => l.startsWith('> '));
      const said = network ? network.slice(2).replace(/^Error: /, '') : '';
      const ip = /^connect (?:ETIMEDOUT|ECONNREFUSED|EHOSTUNREACH) ([\d.]+|[\da-f:]+):\d+$/i.exec(said)?.[1];
      const host = url ? new URL(url).hostname : '';
      const which = ip && host ? ` (the site's address ${ip} did not answer: nslookup ${host} lists every address its name points to; one that never answers is the site's own defect, SITE-06)` : '';
      return `${first.replace(/ failed trying to load:$/, ' could not load')} ${url ?? 'the address'}${said ? `: ${said}` : ''}${which}`;
    }
    const cut = first.indexOf('ms: ');
    return first.startsWith('Timed out retrying after') && cut > 0 ? first.slice(cut + 4) : first;
  },

  /** What is printed when a test fails: the step it failed at, and why. */
  failure(error: Error): string {
    const why = StepLog.reason(error);
    if (!steps.length) return `   FAILED before its first step, because: ${why}`;
    return `   FAILED at step ${steps.length}: ${steps[steps.length - 1]}\n   because: ${why}`;
  },
};

